package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.equipment.TreeFertilizerSimulation;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BeehiveBlockEntity;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.phys.*;

/** Proposed actual-native detached-growth/replay/custody/error cases. Runtime and mixin weaving UNRUN. */
public final class FertilizerGameTests {
 private static final BlockPos P=new BlockPos(3,3,3);
 private static BlockPos plant(GameTestHelper h,Block block,boolean cluster){var p=h.absolutePos(P);for(var offset:BlockPos.betweenClosed(-1,0,-1,1,0,1)){h.getLevel().setBlockAndUpdate(p.offset(offset).below(),Blocks.PODZOL.defaultBlockState());h.getLevel().setBlockAndUpdate(p.offset(offset),cluster?block.defaultBlockState():Blocks.AIR.defaultBlockState());}h.getLevel().setBlockAndUpdate(p,block.defaultBlockState());return p;}
 private static NativeSurvivalTestPlayer player(GameTestHelper h,BlockPos p){return NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(p).add(0,0,3));}
 private static ItemStack stock(){var stack=new ItemStack(AllItems.TREE_FERTILIZER,3);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original native fertilizer stock"));return stack;}
 private static InteractionResult use(net.minecraft.server.level.ServerPlayer player,BlockPos p){return player.gameMode.useItemOn(player,player.level(),player.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(p),Direction.UP,p,false));}
 private static FertilizerTestFixtures.Observation apply(GameTestHelper h,net.minecraft.server.level.ServerPlayer player,BlockPos p,FertilizerTestFixtures.Mode mode){var observed=new FertilizerTestFixtures.Observation();FertilizerTestFixtures.with(new FertilizerTestFixtures.Plan(h.getLevel(),mode,observed,null),()->h.assertTrue(use(player,p).consumesAction(),"Actual native game-mode item use reaches source fertilizer"));return observed;}
 @GameTest public void actualNativeDreamUsesJournalHeightFluidRandomAndRestoresExactOriginalLevelView(GameTestHelper h){var level=h.getLevel();var originalRandom=level.getRandom();var before=level.getBlockState(TreeFertilizerSimulation.ORIGIN);long blockTicks=level.getBlockTicks().count(),fluidTicks=level.getFluidTicks().count();try(var dream=TreeFertilizerSimulation.open(level,Blocks.DIRT.defaultBlockState())){h.assertTrue(level.getRandom()==dream.random&&level.getBlockState(TreeFertilizerSimulation.ORIGIN).isAir()&&level.getBlockState(TreeFertilizerSimulation.ORIGIN.below()).is(Blocks.DIRT),"Actual native Level hooks expose only source soil and AIR in one exact active dream");level.setBlockAndUpdate(TreeFertilizerSimulation.ORIGIN,Blocks.OAK_LOG.defaultBlockState());level.setBlockAndUpdate(TreeFertilizerSimulation.ORIGIN.above(),Blocks.WATER.defaultBlockState());h.assertTrue(level.getFluidState(TreeFertilizerSimulation.ORIGIN.above()).isSource()&&level.getHeight(Heightmap.Types.WORLD_SURFACE,0,0)==12,"Actual native fluid and height queries derive from source journal without real chunks");level.scheduleTick(TreeFertilizerSimulation.ORIGIN,Blocks.OAK_LOG,1);level.scheduleTick(TreeFertilizerSimulation.ORIGIN.above(),net.minecraft.world.level.material.Fluids.WATER,1);boolean refused=false;try{level.getChunkSource().getChunkNow(0,0);}catch(UnsupportedOperationException expected){refused=true;}h.assertTrue(refused,"Any original native chunk lookup fails before cache access, without fabricated readiness");}h.assertTrue(level.getRandom()==originalRandom&&level.getBlockState(TreeFertilizerSimulation.ORIGIN)==before&&level.getBlockTicks().count()==blockTicks&&level.getFluidTicks().count()==fluidTicks&&TreeFertilizerSimulation.active(level)==null,"Native original random, physical block and actual scheduled queues remain unchanged after scope cleanup");h.succeed();}
 @GameTest public void actualSourceClusterForcesStageOneNormalizesDirtAndPaysOriginalFiniteStock(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,true);try(var joined=player(h,p)){var player=joined.player();var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);var observed=apply(h,player,p,FertilizerTestFixtures.Mode.NORMAL);h.assertTrue(observed.saplings==9&&observed.allStageOne&&observed.soil.is(Blocks.DIRT)&&observed.soilAfter.is(Blocks.DIRT)&&observed.air&&observed.random&&observed.detachedHive,"Genuine BonemealableBlock callback receives source nine matching stage1 saplings, normalized constant soil, detached AIR/random and native detached hive: saplings="+observed.saplings+", allStageOne="+observed.allStageOne+", soil="+observed.soil+", soilAfter="+observed.soilAfter+", air="+observed.air+", random="+observed.random+", detachedHive="+observed.detachedHive);h.assertTrue(player.getMainHandItem()==original&&original.getCount()==2&&original.getHoverName().getString().equals("Original native fertilizer stock")&&h.getLevel().getBlockState(p).is(Blocks.OAK_LOG)&&h.getLevel().getBlockState(p.below()).is(Blocks.ROOTED_DIRT)&&h.getLevel().getBlockState(p.north().east()).is(FertilizerTestFixtures.SAPLING),"Accepted real replay debits one exact original named fertilizer, preserves source ignored-podzol write and publishes native rooted dirt");}h.succeed();}
 @GameTest public void actualMixedThreeByThreeCopiesOnlyClickedSaplingBlock(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);h.getLevel().setBlockAndUpdate(p.east(),FertilizerTestFixtures.SAPLING.defaultBlockState().setValue(SaplingBlock.STAGE,1));h.getLevel().setBlockAndUpdate(p.west(),Blocks.BIRCH_SAPLING.defaultBlockState());try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,stock());var observed=apply(h,player,p,FertilizerTestFixtures.Mode.NORMAL);h.assertTrue(observed.saplings==2&&observed.allStageOne,"Original source matching-block filter admits only two real source saplings to its virtual3x3");}h.succeed();}
 @GameTest public void actualReplayProtectsBedrockAndSolidBlocksFromLeavesButLogsReplaceRealSolid(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);h.getLevel().setBlockAndUpdate(p.north(),Blocks.BEDROCK.defaultBlockState());h.getLevel().setBlockAndUpdate(p.west(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(p.east(),Blocks.STONE.defaultBlockState());try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,stock());apply(h,player,p,FertilizerTestFixtures.Mode.NORMAL);h.assertTrue(h.getLevel().getBlockState(p.north()).is(Blocks.BEDROCK)&&h.getLevel().getBlockState(p.west()).is(Blocks.STONE)&&h.getLevel().getBlockState(p.east()).is(Blocks.OAK_LOG),"Actual source replay skips destroy-speed-1 and nonconductor collision replacement while a real native conducting log replaces stone");}h.succeed();}
 @GameTest public void genuineNativeBeeOccupantsReachOnlyAcceptedRealHiveWithoutRewritingOtherComponents(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,stock());apply(h,player,p,FertilizerTestFixtures.Mode.NORMAL);var hive=(BeehiveBlockEntity)h.getLevel().getBlockEntity(p.south());var bees=hive.collectComponents().getOrDefault(DataComponents.BEES,net.minecraft.world.item.component.Bees.EMPTY).bees();h.assertTrue(hive.getLevel()==h.getLevel()&&bees!=null&&bees.size()==2&&bees.get(0).ticksInHive()==20&&bees.get(1).ticksInHive()==40,"Only accepted genuine native hive receives the two original native typed occupants with exact saved times");}h.succeed();}
 @GameTest public void nativeGeneratedEntityIsAdmittedExactlyOnceAfterItsRealAnchorWrite(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,stock());var observed=apply(h,player,p,FertilizerTestFixtures.Mode.ENTITY);var entity=observed.entity;h.assertTrue(entity!=null&&h.getLevel().getEntity(entity.getUUID())==entity&&Math.abs(entity.getX()-(p.getX()+.5))<.001&&Math.abs(entity.getY()-(p.getY()+1))<.001&&Math.abs(entity.getZ()-(p.getZ()-.5))<.001,"Actual native generated entity keeps one exact UUID/reference owner and receives only accepted real-coordinate admission");}h.succeed();}
 @GameTest public void rejectedRealAnchorCannotAdmitDeferredNativeEntity(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);h.getLevel().setBlockAndUpdate(p.north(),Blocks.BEDROCK.defaultBlockState());try(var joined=player(h,p)){var player=joined.player();player.setItemInHand(InteractionHand.MAIN_HAND,stock());var observed=apply(h,player,p,FertilizerTestFixtures.Mode.ENTITY);h.assertTrue(observed.entity!=null&&h.getLevel().getEntity(observed.entity.getUUID())==null&&h.getLevel().getBlockState(p.north()).is(Blocks.BEDROCK),"A genuine deferred entity cannot publish when its exact replay anchor is rejected");}h.succeed();}
 @GameTest public void realBonemealCallbackErrorClosesNativeDreamWithoutReplayOrOriginalStockDebit(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);try(var joined=player(h,p)){var player=joined.player();var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);var failure=new FertilizerTestFixtures.NativeRefusal();boolean thrown=false;try{FertilizerTestFixtures.with(new FertilizerTestFixtures.Plan(h.getLevel(),FertilizerTestFixtures.Mode.ERROR,new FertilizerTestFixtures.Observation(),failure),()->use(player,p));}catch(Throwable actual){while(actual!=null&&actual!=failure)actual=actual.getCause();h.assertTrue(actual==failure,"Native game-mode propagation retains the exact genuine callback Error");thrown=true;}h.assertTrue(thrown&&TreeFertilizerSimulation.active(h.getLevel())==null&&player.getMainHandItem()==original&&original.getCount()==3&&h.getLevel().getBlockState(p).is(FertilizerTestFixtures.SAPLING),"Real native callback failure cleans only thread scope; original stock/physical sapling remain without synthetic rollback");}h.succeed();}
 @GameTest public void unknownAddonBlockEntityGuardRefusesBeforeOriginalWorldAccess(GameTestHelper h){var p=plant(h,FertilizerTestFixtures.SAPLING,false);try(var joined=player(h,p)){var player=joined.player();var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);boolean refused=false;try{apply(h,player,p,FertilizerTestFixtures.Mode.UNKNOWN_BE);}catch(Throwable failure){while(failure!=null&&!(failure instanceof UnsupportedOperationException))failure=failure.getCause();refused=failure instanceof UnsupportedOperationException;}h.assertTrue(refused&&original.getCount()==3&&h.getLevel().getBlockState(p).is(FertilizerTestFixtures.SAPLING)&&TreeFertilizerSimulation.active(h.getLevel())==null,"Unsupported addon BE cannot silently use an actual chunk, erase stock or leave a native overlay active");}h.succeed();}
 @GameTest public void actualNativeOakTreeFeatureRunsThroughSourceDetachedSimulation(GameTestHelper h){var p=plant(h,Blocks.OAK_SAPLING,true);try(var joined=player(h,p)){var player=joined.player();var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);h.assertTrue(use(player,p).consumesAction()&&original.getCount()==2&&h.getLevel().getBlockState(p).is(Blocks.OAK_LOG)&&TreeFertilizerSimulation.active(h.getLevel())==null,"Genuine native TreeGrower/tree/trunk/foliage path grows a real oak with the source forced-stage dream and one original fertilizer charge");}h.succeed();}
 @GameTest public void actualNativeMangroveRootFeatureRunsThroughSourceDetachedSimulation(GameTestHelper h){var p=plant(h,Blocks.MANGROVE_PROPAGULE,false);try(var joined=player(h,p)){var player=joined.player();var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);h.assertTrue(use(player,p).consumesAction()&&original.getCount()==2&&TreeFertilizerSimulation.active(h.getLevel())==null,"Genuine native mangrove root/trunk/foliage/decorator path completes source detached execution and charge");int logs=0;for(var cell:BlockPos.betweenClosed(p.offset(-4,0,-4),p.offset(4,18,4)))if(h.getLevel().getBlockState(cell).is(Blocks.MANGROVE_LOG))logs++;h.assertTrue(logs>0,"Native genuine mangrove source feature publishes actual logs, not ordinary bonemeal placeholder success");}h.succeed();}
 @GameTest public void hangingNativePropaguleAndUnrelatedBlocksCannotConsumeOriginalFertilizer(GameTestHelper h){var p=plant(h,Blocks.MANGROVE_PROPAGULE,false);h.getLevel().setBlockAndUpdate(p.above(),Blocks.MANGROVE_LEAVES.defaultBlockState());h.getLevel().setBlockAndUpdate(p,Blocks.MANGROVE_PROPAGULE.defaultBlockState().setValue(MangrovePropaguleBlock.HANGING,true));try(var joined=player(h,p)){var player=joined.player();var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);use(player,p);h.assertValueEqual(original.getCount(),3,"Original source hanging propagule exclusion preserves actual stock");h.getLevel().setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());use(player,p);h.assertValueEqual(original.getCount(),3,"Non-sapling native target cannot consume original fertilizer");}h.succeed();}
 @GameTest public void genuineNativeFlowerBoxScanReadsOnlyCurrentDreamJournal(GameTestHelper h){
  var level=h.getLevel();var origin=TreeFertilizerSimulation.ORIGIN;var flower=origin.above();var found=new java.util.ArrayList<BlockPos>();
  try(var dream=TreeFertilizerSimulation.open(level,Blocks.DIRT.defaultBlockState())){
   h.assertFalse(level.findBlocksIn(origin.offset(-2,-1,-2),origin.offset(2,1,2)).filterState(state->state.is(net.minecraft.tags.BlockTags.FLOWERS)).anyMatched(),"Actual native TreeGrower flower-box consumer initially sees only journal AIR and normalized source soil");
   level.setBlockAndUpdate(flower,Blocks.DANDELION.defaultBlockState());
   level.findBlocksIn(origin.offset(2,1,2),origin.offset(-2,-1,-2)).filterState(state->state.is(net.minecraft.tags.BlockTags.FLOWERS)).forEach((pos,state)->found.add(pos.immutable()));
   h.assertTrue(found.equals(java.util.List.of(flower))&&level.findBlocksIn(origin.offset(-2,-1,-2),origin.offset(2,1,2)).filterState(state->state.is(net.minecraft.tags.BlockTags.FLOWERS)).anyMatched(),"Native box scan with reversed endpoints visits exactly the current detached flower and retains its real predicate/consumer result without original chunks");
   level.setBlockAndUpdate(flower,Blocks.AIR.defaultBlockState());
   h.assertFalse(level.findBlocksIn(origin.offset(-2,-1,-2),origin.offset(2,1,2)).filterState(state->state.is(net.minecraft.tags.BlockTags.FLOWERS)).anyMatched(),"A later real journal write is visible to a fresh native flower scan without stale cached source sections");
  }
  h.assertTrue(TreeFertilizerSimulation.active(level)==null,"Native box scan leaves no dream owner after scope cleanup");h.succeed();
 }
 @GameTest public void originalDirtFamilyAndNativePaleMossNormalizeOnlyTheDetachedSoil(GameTestHelper h){
  var soils=java.util.List.of(Blocks.DIRT,Blocks.GRASS_BLOCK,Blocks.PODZOL,Blocks.COARSE_DIRT,Blocks.MYCELIUM,Blocks.ROOTED_DIRT,Blocks.MOSS_BLOCK,Blocks.MUD,Blocks.MUDDY_MANGROVE_ROOTS,Blocks.PALE_MOSS_BLOCK,Blocks.FARMLAND);
  var p=h.absolutePos(P);
  try(var joined=player(h,p)){var player=joined.player();
   for(var soil:soils){
    plant(h,FertilizerTestFixtures.SAPLING,false);var physical=soil.defaultBlockState();h.getLevel().setBlockAndUpdate(p.below(),physical);
    h.assertTrue(h.getLevel().getBlockState(p).is(FertilizerTestFixtures.SAPLING),"Genuine native sapling survives actual source soil "+soil);
    var original=stock();player.setItemInHand(InteractionHand.MAIN_HAND,original);var observed=new FertilizerTestFixtures.Observation();var failure=new FertilizerTestFixtures.NativeRefusal();boolean thrown=false;
    try{FertilizerTestFixtures.with(new FertilizerTestFixtures.Plan(h.getLevel(),FertilizerTestFixtures.Mode.ERROR,observed,failure),()->use(player,p));}
    catch(Throwable actual){while(actual!=null&&actual!=failure)actual=actual.getCause();h.assertTrue(actual==failure,"Actual native soil observation preserves the exact genuine callback Error for "+soil);thrown=true;}
    h.assertTrue(thrown&&observed.soil!=null&&observed.soil.is(soil==Blocks.FARMLAND?Blocks.FARMLAND:Blocks.DIRT),"All nine original source substrates plus native pale moss normalize to DIRT; genuine native FARMLAND retains its distinct source soil: "+soil+" -> "+observed.soil);
    h.assertTrue(h.getLevel().getBlockState(p.below())==physical&&h.getLevel().getBlockState(p).is(FertilizerTestFixtures.SAPLING)&&player.getMainHandItem()==original&&original.getCount()==3&&TreeFertilizerSimulation.active(h.getLevel())==null,"Only detached soil is normalized; actual physical soil, sapling and all three original named fertilizer items survive native callback failure for "+soil);
   }
  }h.succeed();
 }
}
